import sys
import types
from unittest.mock import DEFAULT, patch

from _pytest.compat import getfuncargnames, num_mock_patch_args


class AmbiguousBool:
    def __bool__(self):
        raise ValueError("array truth value is ambiguous")


class ArrayLike:
    """Mimics multi-element numpy array equality behavior."""

    def __eq__(self, other):
        return AmbiguousBool()


ARRAY = ArrayLike()


@patch("os.getcwd", new=ARRAY)
def explicit(x):
    pass


@patch("os.getcwd")
def default(x):
    pass


@patch.object(object, "__doc__", "changed")
def attribute(x):
    pass


@patch("os.getcwd")
@patch("os.getcwd", new=ARRAY)
def mixed(x, y):
    pass


assert num_mock_patch_args(explicit) == 0
assert num_mock_patch_args(default) == 1
assert num_mock_patch_args(attribute) == 0
assert num_mock_patch_args(mixed) == 1

assert getfuncargnames(explicit) == ("x",)
assert getfuncargnames(default) == ()
assert getfuncargnames(attribute) == ("x",)
assert getfuncargnames(mixed) == ("y",)

# The legacy mock module's distinct DEFAULT sentinel is also recognized.
mock_module = types.ModuleType("mock")
mock_module.DEFAULT = object()
sys.modules["mock"] = mock_module

def legacy_default_patchings(x):
    pass

legacy_default_patchings.patchings = [types.SimpleNamespace(new=mock_module.DEFAULT, attribute_name=None)]
legacy_default_patchings.__wrapped__ = lambda: None
assert num_mock_patch_args(legacy_default_patchings) == 1

# Preserve the historical fallback when neither mock module is loaded.
del sys.modules["mock"]
del sys.modules["unittest.mock"]

def no_mocks(x, y):
    pass

no_mocks.patchings = [
    types.SimpleNamespace(new=ARRAY, attribute_name=None),
    types.SimpleNamespace(new=object(), attribute_name=None),
]
no_mocks.__wrapped__ = lambda: None
assert num_mock_patch_args(no_mocks) == 2

print("edge-case helper checks: PASS")
PY
